import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const p=JSON.parse('{"title":"Features by hub & menu","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md","lastUpdated":1794736181000}'),n={name:"features.md"};function a(d,t,i,g,c,h){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="features-by-hub-menu" tabindex="-1">Features by hub &amp; menu <a class="header-anchor" href="#features-by-hub-menu" aria-label="Permalink to &quot;Features by hub &amp; menu&quot;">​</a></h1><p>A complete feature map of <strong>Rakkii Ops</strong>, organized in the exact order of the app&#39;s six hubs and side menus. Use this page to find which hub and screen handles a task, who sees it, and which guide covers the steps.</p><div class="info custom-block"><p class="custom-block-title">Admin / Service Advisor in v2</p><p>This guide covers the <strong>Shop Owner</strong>, <strong>Lead Technician</strong>, and <strong>Sales Agent</strong> roles. <strong>Admin / Service Advisor</strong> is <strong>To be decided — Waiting for confirmation.</strong> Where the app supports <code>admin</code> on desk screens, its day-to-day scope is not yet finalized in this guide.</p></div><h2 id="role-access-at-a-glance" tabindex="-1">Role access at a glance <a class="header-anchor" href="#role-access-at-a-glance" aria-label="Permalink to &quot;Role access at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Role key</th><th>Hubs in menu</th><th>Home screen</th><th>Read</th></tr></thead><tbody><tr><td><strong>Shop Owner</strong></td><td><code>owner</code></td><td><strong>Workshop</strong>, <strong>Sales</strong>, <strong>Finance</strong>, <strong>HR</strong>, <strong>Admin</strong>, <strong>Me</strong></td><td><strong>Workshop › Dashboard</strong> (<code>/workshop</code>)</td><td><a href="/rakkii-cars-guide/start/getting-started">Start here</a>, <a href="/rakkii-cars-guide/desk/">Owner / desk</a></td></tr><tr><td><strong>Lead Technician</strong></td><td><code>technician</code></td><td><strong>Workshop</strong>, <strong>Me</strong></td><td><strong>Workshop › My jobs</strong> (<code>/workshop</code>)</td><td><a href="/rakkii-cars-guide/start/getting-started">Start here</a>, <a href="/rakkii-cars-guide/technician/">Technician</a>, <a href="/rakkii-cars-guide/me/">Me hub</a></td></tr><tr><td><strong>Sales Agent</strong></td><td><code>sales</code></td><td><strong>Sales</strong>, <strong>Me</strong></td><td><strong>Sales › My pipeline</strong> (<code>/sales/pipeline</code>)</td><td><a href="/rakkii-cars-guide/start/getting-started">Start here</a>, <a href="/rakkii-cars-guide/sales/">Sales agent</a>, <a href="/rakkii-cars-guide/me/">Me hub</a></td></tr><tr><td><strong>Admin / Service Advisor</strong></td><td><code>admin</code></td><td>To be decided — Waiting for confirmation.</td><td>To be decided — Waiting for confirmation.</td><td>—</td></tr></tbody></table><h2 id="top-bar-global-tools" tabindex="-1">Top bar &amp; global tools <a class="header-anchor" href="#top-bar-global-tools" aria-label="Permalink to &quot;Top bar &amp; global tools&quot;">​</a></h2><p>Available across hubs from the app header (<a href="/rakkii-cars-guide/start/getting-started">Getting started</a>):</p><ul><li><strong>Switch shop branch</strong> — Appears in the top bar for head-office owners with more than one shop. Switches all hubs, jobs, money, and staff views to the selected branch.</li><li><strong>Switch module (Hub switcher)</strong> — Moves between the hubs your role can open (<strong>Workshop</strong>, <strong>Sales</strong>, <strong>Finance</strong>, <strong>HR</strong>, <strong>Admin</strong>, <strong>Me</strong>). Shows the remaining <strong>Shop setup</strong> count next to <strong>Admin</strong>.</li><li><strong>Quick search</strong> (<kbd>/</kbd>, placeholder <strong>Plate, job or customer</strong>) — Searches open and finished jobs by plate, job reference, or customer name from anywhere in the app (<strong>Shop Owner</strong>, <strong>Lead Technician</strong>).</li><li><strong>Customer activity bell</strong> — Shows an unseen count badge for online customer actions and opens <strong>Workshop › Customer activity</strong> (<strong>Shop Owner</strong>).</li><li><strong>Account menu</strong> — Shows your name, role, and avatar/initials, with shortcuts to <strong>My profile</strong> (everyone), <strong>Settings</strong> (<strong>Shop Owner</strong>), <strong>Dark mode</strong> / <strong>Light mode</strong>, and <strong>Sign out</strong>.</li></ul><hr><h2 id="_1-workshop-hub-workshop" tabindex="-1">1. Workshop hub (<code>/workshop</code>) <a class="header-anchor" href="#_1-workshop-hub-workshop" aria-label="Permalink to &quot;1. Workshop hub (`/workshop`)&quot;">​</a></h2><p>Daily repair operations: active jobs, appointments, customers, vehicles, parts, insurers, and paper forms.</p><h3 id="pinned-shortcuts" tabindex="-1">Pinned shortcuts <a class="header-anchor" href="#pinned-shortcuts" aria-label="Permalink to &quot;Pinned shortcuts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td><code>/workshop</code></td><td>Shop Owner</td><td>Daily shop overview: metrics (<strong>Cars on the floor</strong>, <strong>Jobs open</strong>, <strong>Ready for pickup</strong>, <strong>On hold</strong>, <strong>Cash in today</strong>, <strong>Overdue invoices</strong>), <strong>Announcements</strong>, <strong>Due today</strong>, <strong>New web &amp; Messenger inquiries</strong>, <strong>Today&#39;s appointments</strong>, <strong>Cars in the shop</strong> mix, <strong>Ready, but customer still owes</strong>, and <strong>Priority jobs</strong>.</td><td><a href="/rakkii-cars-guide/desk/">Your day at the desk</a></td></tr><tr><td><strong>My jobs</strong></td><td><code>/workshop</code></td><td>Lead Technician</td><td>Technician home screen: <strong>Clock in</strong> / <strong>Clock out</strong> shortcut, <strong>Announcements</strong>, <strong>Priority jobs</strong>, <strong>Assigned to me</strong>, <strong>Done, waiting for pickup</strong>, <strong>Other cars on the floor</strong>, and <strong>Today&#39;s appointments</strong>.</td><td><a href="/rakkii-cars-guide/technician/">Your day in the bay</a></td></tr><tr><td><strong>Shop board</strong></td><td><code>/workshop/board</code></td><td>Shop Owner</td><td>Visual <strong>Columns</strong> (five-lane kanban) and <strong>List</strong> views of active jobs, filterable by type (<strong>Retail</strong>, <strong>Insurance</strong>, <strong>Fleet</strong>), lane, target date, stuck status, work category, or search, with <strong>What&#39;s left</strong> popups.</td><td><a href="/rakkii-cars-guide/desk/board-and-calendar">Board, calendar &amp; search</a></td></tr><tr><td><strong>New job</strong></td><td><code>/workshop/jobs/new</code></td><td>Shop Owner</td><td>Opens a new repair job from <strong>Customer</strong>, <strong>Vehicle</strong>, <strong>Work</strong>, optional <strong>How the job came in</strong> (channel, VAT/Non-VAT, sales advisor, referral), and <strong>Insurance</strong> details.</td><td><a href="/rakkii-cars-guide/desk/job/01-open-a-job">1. Open a job</a></td></tr></tbody></table><h3 id="workshop-menu" tabindex="-1">Workshop menu <a class="header-anchor" href="#workshop-menu" aria-label="Permalink to &quot;Workshop menu&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Customer activity</strong></td><td><code>/workshop/activity</code></td><td>Shop Owner</td><td>Feed of online Customer Portal actions (bookings, estimate decisions, uploaded payment proofs) with <strong>Unseen</strong> / <strong>All</strong> filters and <strong>Mark seen</strong> / <strong>Mark all seen</strong>.</td><td><a href="/rakkii-cars-guide/desk/board-and-calendar">Board, calendar &amp; search</a></td></tr><tr><td><strong>Calendar</strong></td><td><code>/workshop/calendar</code></td><td>Shop Owner, Lead Technician</td><td>Week-by-week schedule of appointments and target dates, unscheduled jobs list, and <strong>Book this day</strong> shortcut to <strong>New job</strong>.</td><td><a href="/rakkii-cars-guide/desk/board-and-calendar">Board, calendar &amp; search</a></td></tr><tr><td><strong>Job history</strong></td><td><code>/workshop/jobs</code></td><td>Shop Owner, Lead Technician</td><td>Searchable archive of jobs filtered by plate/reference, date range, job type, and status (<strong>All finished</strong>, <strong>Released · not done</strong>, <strong>Done</strong>) with a <strong>Progress</strong> column.</td><td><a href="/rakkii-cars-guide/start/getting-started">Getting started</a></td></tr><tr><td><strong>Backjobs</strong></td><td><code>/workshop/backjobs</code></td><td>Shop Owner</td><td>Monthly monitor of rework/backjob incidents, shop-absorbed costs, breakdown by responsible staff, and open backjobs.</td><td><a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/10-workshop-operations-board-calendar-backjobs-contractors">Ref 10</a></td></tr><tr><td><strong>Contractor jobs</strong></td><td><code>/workshop/contractors</code></td><td>Shop Owner</td><td>Tracks outsourced/subcontracted job lines by status, contractor, overdue/due-today commitments, and remaining balances.</td><td><a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/10-workshop-operations-board-calendar-backjobs-contractors">Ref 10</a></td></tr><tr><td><strong>Customers</strong></td><td><code>/workshop/customers</code></td><td>Shop Owner</td><td>Customer directory with search, customer creation, and drilldowns to customer detail (<code>/workshop/customers/:id</code>) and vehicle detail (<code>/workshop/vehicles/:id</code>) service histories.</td><td><a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/desk/corporate-jobs">Corporate jobs</a></td></tr><tr><td><strong>Parts &amp; Inventory</strong></td><td><code>/workshop/parts</code></td><td>Shop Owner</td><td><strong>Stock</strong> catalog (on-hand counts, low-stock alerts, stock value, receive/adjust/movements, bulk categories) and <strong>Restock POs</strong> ordering workflow.</td><td><a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">Ref 9</a></td></tr><tr><td><strong>Insurers</strong></td><td><code>/workshop/insurers</code></td><td>Shop Owner</td><td>Directory of insurance companies with expected days to pay, payment terms, and contact details.</td><td><a href="/rakkii-cars-guide/desk/insurance-jobs">Insurance jobs</a>, <a href="/rakkii-cars-guide/reference/06-lane-2-insurance-claims-and-loa">Ref 6</a></td></tr><tr><td><strong>Forms</strong></td><td><code>/workshop/forms</code></td><td>Shop Owner, Lead Technician</td><td>Printable and fillable forms organized by stage: <strong>Car in</strong> (Undertaking &amp; vehicle intake checklist), <strong>Pick-up / delivery</strong> (VD waiver), and <strong>Car out</strong> (Gate pass, acceptance, Release of claim).</td><td><a href="/rakkii-cars-guide/technician/">Your day in the bay</a>, <a href="/rakkii-cars-guide/desk/job/07-release">Release the car</a></td></tr></tbody></table><h3 id="job-workspace-workshop-jobs-id" tabindex="-1">Job workspace (<code>/workshop/jobs/:id</code>) <a class="header-anchor" href="#job-workspace-workshop-jobs-id" aria-label="Permalink to &quot;Job workspace (`/workshop/jobs/:id`)&quot;">​</a></h3><p>Opening any job shows the header (with <strong>More ▾</strong> for <strong>Put on hold</strong>, <strong>Cancel job</strong>, <strong>No-show</strong>, and car/customer edits), the seven-step <strong>Progress</strong> card (<strong>Created</strong>, <strong>Booked</strong>, <strong>Work done</strong>, <strong>QC passed</strong>, <strong>Released</strong>, <strong>Paid</strong>, <strong>Done</strong>) with a blue <strong>next-step button</strong> (<a href="/rakkii-cars-guide/start/getting-started#job-page">Getting started</a>), and up to eight role- and job-gated tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Who sees it</th><th>What it covers</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>Shop Owner, Sales Agent (read-only on own jobs)</td><td><strong>Job</strong>, <strong>Money</strong>, <strong>Release</strong>, <strong>Backjobs</strong>, and collapsible <strong>Status log</strong> cards.</td><td><a href="/rakkii-cars-guide/start/getting-started#job-page">Getting started</a></td></tr><tr><td><strong>Canvass</strong></td><td>Shop Owner; Lead Technician (read-only when enabled)</td><td>Up to four supplier quotes per part (grade, chosen supplier, RFP status, budget vs. estimate check).</td><td><a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">Ref 9</a></td></tr><tr><td><strong>Parts buy</strong></td><td>Shop Owner; Lead Technician (when enabled)</td><td>Job-specific parts purchases, supplier payment terms, and purchase bills.</td><td><a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">Ref 9</a></td></tr><tr><td><strong>Work</strong></td><td>Shop Owner, Lead Technician</td><td><strong>Work lines</strong>, the <strong>Quote</strong> card (no separate Quote tab), <strong>Team</strong> &amp; <strong>Dates</strong>, <strong>Bay checklist</strong>, <strong>QC photos</strong> (4 angles), <strong>Notes</strong>, <strong>Other photo</strong>, and job order printing.</td><td><a href="/rakkii-cars-guide/desk/job/02-work-and-quote">2. Work &amp; quote</a>, <a href="/rakkii-cars-guide/desk/job/04-start-work">4. Start work</a></td></tr><tr><td><strong>Insurance</strong></td><td>Shop Owner (insurance jobs only)</td><td><strong>Claim status</strong>, <strong>What is blocking</strong>, <strong>Letter of authorization</strong>, and <strong>Supplements</strong>.</td><td><a href="/rakkii-cars-guide/desk/insurance-jobs">Insurance jobs</a></td></tr><tr><td><strong>Pay</strong></td><td>Shop Owner</td><td><strong>Summary</strong>, <strong>Invoices</strong> (including split Customer/Insurer billing), <strong>Record a payment</strong>, <strong>Payments</strong>, <strong>Nature and PO</strong>, <strong>Down payment</strong>, <strong>Withholding</strong>, and <strong>Commission and agent fee</strong>.</td><td><a href="/rakkii-cars-guide/desk/job/06-bill-and-collect">6. Bill &amp; collect</a></td></tr><tr><td><strong>Files</strong></td><td>Shop Owner, Lead Technician</td><td>Required document checklist (<strong>Documents</strong>) and uploaded job attachments (<strong>Files</strong>).</td><td><a href="/rakkii-cars-guide/desk/job/01-open-a-job">1. Open a job</a></td></tr><tr><td><strong>Release</strong></td><td>Shop Owner</td><td><strong>Can the car leave?</strong> checklist, <strong>Release the car</strong> (plus <strong>Owner override</strong>), <strong>PMS reminder</strong> (3/6/12 months), <strong>Surrendered parts</strong>, <strong>Release rules</strong>, gate pass, acceptance, and Release of claim prints.</td><td><a href="/rakkii-cars-guide/desk/job/07-release">7. Release the car</a></td></tr></tbody></table><hr><h2 id="_2-sales-hub-sales" tabindex="-1">2. Sales hub (<code>/sales</code>) <a class="header-anchor" href="#_2-sales-hub-sales" aria-label="Permalink to &quot;2. Sales hub (`/sales`)&quot;">​</a></h2><p>Lead tracking, sales quota monitoring, commissions, quarterly incentives, and auto insurance estimates (<a href="/rakkii-cars-guide/sales/">Your day in sales</a>).</p><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Pipeline</strong> / <strong>My pipeline</strong></td><td><code>/sales/pipeline</code></td><td>Shop Owner (<strong>Pipeline</strong>), Sales Agent (<strong>My pipeline</strong>)</td><td>Tracks inquiries from first contact to estimate/booking, with follow-up alerts, quote freshness, <strong>Set follow-up</strong>, <strong>Print estimate</strong>, and <strong>Mark lost</strong>.</td><td><a href="/rakkii-cars-guide/sales/">Your day in sales</a></td></tr><tr><td><strong>Commission</strong> / <strong>My commission</strong></td><td><code>/sales</code></td><td>Shop Owner (<strong>Commission</strong>), Sales Agent (<strong>My commission</strong>)</td><td>Four-step commission funnel (<strong>Accruing → Due → Approved → Paid</strong>), clawback review, <strong>Approve</strong> / <strong>Reject</strong> / <strong>Pay due fees</strong> (<strong>Shop Owner</strong>), and <strong>Export CSV</strong>.</td><td><a href="/rakkii-cars-guide/sales/">Your day in sales</a></td></tr><tr><td><strong>Monitoring</strong></td><td><code>/sales/monitoring</code></td><td>Shop Owner, Sales Agent</td><td>Monthly quota progress and <strong>Leaderboard</strong> / <strong>My performance</strong>; <strong>Shop Owner</strong> also sees <strong>Sales mix</strong> reconciliation, <strong>Imports &amp; quota history</strong> (Excel import/undo), and inline quota edits.</td><td><a href="/rakkii-cars-guide/sales/">Your day in sales</a></td></tr><tr><td><strong>Incentives</strong></td><td><code>/sales/incentives</code></td><td>Shop Owner (in menu); Sales Agent (via <strong>My incentive</strong> in <strong>Me</strong> or <strong>My commission</strong>)</td><td>Quarterly unit sales targets and bonus lines; <strong>Shop Owner</strong> can <strong>Set a target</strong>, <strong>Record bonus</strong>, move, or void bonus lines.</td><td><a href="/rakkii-cars-guide/sales/">Your day in sales</a></td></tr><tr><td><strong>Insurance</strong></td><td><code>/sales/insurance</code></td><td>Shop Owner, Sales Agent</td><td>Auto insurance <strong>Estimate</strong> calculator (<code>TPL</code> / <code>Comprehensive</code>, value band, add-ons, saved estimate prints) plus <strong>Rates</strong> setup (<strong>Shop Owner</strong> only).</td><td><a href="/rakkii-cars-guide/sales/">Your day in sales</a></td></tr></tbody></table><hr><h2 id="_3-finance-hub-finance" tabindex="-1">3. Finance hub (<code>/finance</code>) <a class="header-anchor" href="#_3-finance-hub-finance" aria-label="Permalink to &quot;3. Finance hub (`/finance`)&quot;">​</a></h2><p>Cash visibility, collections, supplier bills, expenses, reporting, month-end close, and accounting exports. The side menu is split into <strong>daily</strong> screens and <strong>periodic &amp; setup</strong> screens.</p><h3 id="daily-screens" tabindex="-1">Daily screens <a class="header-anchor" href="#daily-screens" aria-label="Permalink to &quot;Daily screens&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Cash</strong></td><td><code>/finance/cash</code></td><td>Shop Owner</td><td>Today&#39;s cash flow (<strong>In</strong> / <strong>Out</strong> / <strong>Net</strong>), <strong>Open AR</strong>, <strong>Payables due</strong>, daily <strong>Cash in</strong> chart, customer vs. insurer aging, and follow-up lists (<strong>Waiting to be billed</strong>, <strong>Authorized, not started</strong>).</td><td><a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr><tr><td><strong>Payments</strong></td><td><code>/finance/payments</code></td><td>Shop Owner</td><td><strong>Payments</strong> log (search, payer/method/date filters, <strong>Export CSV</strong>, <strong>Print</strong>, <strong>Void</strong>) and <strong>Pending proofs</strong> to <strong>Confirm</strong> or <strong>Reject</strong> Customer Portal payment screenshots.</td><td><a href="/rakkii-cars-guide/desk/job/06-bill-and-collect">6. Bill &amp; collect</a>, <a href="/rakkii-cars-guide/desk/fix-a-mistake">Fix a mistake</a></td></tr><tr><td><strong>Who owes us</strong></td><td><code>/finance/receivables</code></td><td>Shop Owner</td><td>Open accounts receivable with aging buckets, insurer running days, follow-up logging, and billing transmittals.</td><td><a href="/rakkii-cars-guide/reference/08-lane-4-billing-chain-receivables-storage-credit-notes">Ref 8</a></td></tr><tr><td><strong>Payables</strong></td><td><code>/finance/payables</code></td><td>Shop Owner</td><td>Supplier <strong>Bills</strong> (<strong>Due soon</strong>, <strong>Overdue</strong>, <strong>Open</strong>, <strong>Paid</strong>) from parts buys and restock POs, <strong>Pay</strong> / <strong>View payments</strong>, and <strong>Per supplier</strong> balances.</td><td><a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">Ref 9</a></td></tr><tr><td><strong>Expenses</strong></td><td><code>/finance/expenses</code></td><td>Shop Owner</td><td>Monthly shop expense log by category with VAT split, paid-from account tracking, <strong>Add expense</strong>, <strong>Void</strong>, <strong>Export CSV</strong>, and <strong>Print</strong>.</td><td><a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr><tr><td><strong>Accounts</strong></td><td><code>/finance/money-accounts</code></td><td>Shop Owner</td><td>Typed wallet balances (Bank, Maya, GCash, Cash on hand), account <strong>Transfer</strong>, <strong>Add account</strong>, <strong>Movements</strong> log, <strong>Adjust</strong>, and balance backfill.</td><td><a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr></tbody></table><h3 id="periodic-setup-screens" tabindex="-1">Periodic &amp; setup screens <a class="header-anchor" href="#periodic-setup-screens" aria-label="Permalink to &quot;Periodic &amp; setup screens&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Reports</strong></td><td><code>/finance/reports</code></td><td>Shop Owner</td><td>Period summaries (<strong>Work billed (before VAT)</strong>, <strong>Cash collected</strong>, <strong>Net cash</strong>) broken down <strong>By type &amp; payer</strong>, <strong>Top accounts</strong> (insurers and fleet/corporate), and <strong>Owed</strong>.</td><td><a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr><tr><td><strong>Job P&amp;L</strong></td><td><code>/finance/pnl</code></td><td>Shop Owner only</td><td><strong>Monthly shop P&amp;L</strong> (net revenue, waterfall, statement, expenses by category) and <strong>Job gross P&amp;L</strong> (per-job revenue, cost split, and margin), with CSV/print exports.</td><td><a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr><tr><td><strong>Blanket POs</strong></td><td><code>/finance/blanket-pos</code></td><td>Shop Owner</td><td>Corporate/government blanket purchase orders (<strong>Open</strong> / <strong>History</strong>), authorized vs. consumed meter, and detail view (<code>/finance/blanket-pos/:id</code>) for linked jobs, aging, model caps, and PO soft copies.</td><td><a href="/rakkii-cars-guide/desk/corporate-jobs">Corporate &amp; government jobs</a>, <a href="/rakkii-cars-guide/reference/07-lane-3-corporate-government-bidding-blanket-pos">Ref 7</a></td></tr><tr><td><strong>Agent fees</strong></td><td><code>/finance/agent-fees</code></td><td>Shop Owner</td><td>Outside/referral agent fee totals by date range with per-agent drilldowns to <strong>Pay</strong> or <strong>Void</strong> fees and flag above-default rates.</td><td><a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr><tr><td><strong>Month close</strong></td><td><code>/finance/month-close</code></td><td>Shop Owner only</td><td>Locks completed accounting months (<strong>Close month</strong>) and logs any <strong>Reopen</strong> action with a required reason.</td><td><a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr><tr><td><strong>Export</strong></td><td><code>/finance/export</code></td><td>Shop Owner</td><td>Bookkeeper CSV downloads by date range for <strong>Invoices</strong>, <strong>Payments</strong>, <strong>Credit notes</strong>, and <strong>Open AR</strong>.</td><td><a href="/rakkii-cars-guide/reference/12-finance-wallets-expenses-agent-fees-pnl-month-close-export">Ref 12</a></td></tr></tbody></table><hr><h2 id="_4-hr-hub-hr" tabindex="-1">4. HR hub (<code>/hr</code>) <a class="header-anchor" href="#_4-hr-hub-hr" aria-label="Permalink to &quot;4. HR hub (`/hr`)&quot;">​</a></h2><p>People records, attendance, leave approvals, shared kiosk clock-in, payroll, announcements, and HR letters (<a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a>).</p><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Directory</strong></td><td><code>/hr/employee-directory</code></td><td>Shop Owner</td><td>Staff list (<strong>Add person</strong>, search, active/inactive) and employee detail (<code>/hr/employee-directory/:id</code>) with <strong>Overview</strong>, <strong>Pay</strong>, <strong>Loans / Cash advance</strong>, <strong>Documents</strong>, <strong>Leave</strong>, <strong>Scorecards</strong>, <strong>History</strong>, and <strong>Issue letter</strong>.</td><td><a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a></td></tr><tr><td><strong>Attendance</strong></td><td><code>/hr/attendance</code></td><td>Shop Owner</td><td>Weekly attendance register (<strong>Monday–Sunday</strong>), <strong>Punches</strong> with in/out photos, <strong>Close</strong> open punches, <strong>Punch for…</strong>, <strong>OT to approve</strong>, and CSV export.</td><td><a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a></td></tr><tr><td><strong>Leave approvals</strong></td><td><code>/hr/leave</code></td><td>Shop Owner</td><td><strong>Needs a decision</strong> queue (<strong>Approve</strong> / <strong>Reject</strong> / <strong>Cancel</strong> with job-reassignment check), <strong>Team balances</strong>, <strong>Add leave</strong>, <strong>Set days</strong> allotments, and leave <strong>History</strong>.</td><td><a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a></td></tr><tr><td><strong>Clock kiosk</strong></td><td><code>/hr/clock-kiosk</code></td><td>Shop Owner</td><td>Shared desk kiosk where staff tap their name to clock in or out without phone GPS.</td><td><a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a></td></tr><tr><td><strong>Documents</strong></td><td><code>/hr/documents</code></td><td>Shop Owner</td><td>Generates HR documents and data sheets: <strong>Notice to explain</strong>, <strong>Notice of decision</strong>, <strong>Quitclaim and release</strong>, <strong>Warning letter</strong>, and <strong>BIR Form 2316</strong> (<code>BIR Form 2307</code> marked <em>Coming soon</em>).</td><td><a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a></td></tr><tr><td><strong>Payroll</strong></td><td><code>/hr/payroll</code></td><td>Shop Owner</td><td>Period payroll register with warnings (open punches, pending OT, missing rates), <strong>Holidays &amp; premiums</strong>, allowances, loans, statutory deductions, <strong>Lock period</strong>, <strong>Void run</strong>, payslip prints, and CSV export.</td><td><a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a></td></tr><tr><td><strong>Announcements</strong></td><td><code>/hr/announcements</code></td><td>Shop Owner</td><td>Creates, edits, and removes shop-wide announcements shown on <strong>Workshop › Dashboard</strong> and <strong>My jobs</strong>.</td><td><a href="/rakkii-cars-guide/reference/11-hr-payroll-kiosk-announcements-documents">Ref 11</a></td></tr></tbody></table><hr><h2 id="_5-admin-hub-admin" tabindex="-1">5. Admin hub (<code>/admin</code>) <a class="header-anchor" href="#_5-admin-hub-admin" aria-label="Permalink to &quot;5. Admin hub (`/admin`)&quot;">​</a></h2><p>Owner-only shop onboarding, configuration, and staff access (<a href="/rakkii-cars-guide/desk/running-the-shop">Running the shop</a>, <a href="/rakkii-cars-guide/reference/13-admin-shop-settings-and-staff-permissions">Ref 13</a>).</p><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Shop setup</strong></td><td><code>/admin/setup</code></td><td>Shop Owner only</td><td>New-shop onboarding checklist (<strong>Before your first car</strong>, <strong>In your first week</strong>) with deep links to settings, <strong>Skip</strong> / <strong>Undo</strong>, and the remaining-count badge on <strong>Admin</strong>.</td><td><a href="/rakkii-cars-guide/reference/13-admin-shop-settings-and-staff-permissions">Ref 13</a></td></tr><tr><td><strong>Shop settings</strong></td><td><code>/admin/settings</code></td><td>Shop Owner only</td><td>Shop and company configuration organized into two areas (see below).</td><td><a href="/rakkii-cars-guide/reference/13-admin-shop-settings-and-staff-permissions">Ref 13</a></td></tr><tr><td><strong>Staff and pay</strong></td><td><code>/admin/staff</code></td><td>Shop Owner only</td><td><strong>Access and pay</strong> table showing each person&#39;s role, home shop, permission badges (<strong>Canvass &amp; pay</strong>, <strong>LOA files</strong>, <strong>LOA amounts</strong>, <strong>Time clock</strong>), pay rate, status, <strong>Resend invite</strong>, and <strong>Activate</strong> / <strong>Deactivate</strong>.</td><td><a href="/rakkii-cars-guide/reference/13-admin-shop-settings-and-staff-permissions">Ref 13</a></td></tr></tbody></table><h3 id="sections-inside-admin-›-shop-settings" tabindex="-1">Sections inside <strong>Admin › Shop settings</strong> <a class="header-anchor" href="#sections-inside-admin-›-shop-settings" aria-label="Permalink to &quot;Sections inside **Admin › Shop settings**&quot;">​</a></h3><ul><li><strong>Shop area</strong> (per-branch): <strong>Getting paid</strong> · <strong>Workshop rules</strong> · <strong>Buying</strong> · <strong>Sales &amp; commission</strong> · <strong>Staff &amp; time</strong> · <strong>Customer site</strong> · <strong>Advanced</strong></li><li><strong>Company area</strong> (head-office owners): <strong>Business details</strong> · <strong>Shops</strong> · <strong>Lists</strong> (<strong>Part grades</strong>, <strong>Part categories</strong>, <strong>Work categories</strong>, <strong>Expense categories</strong>, <strong>Checklists</strong>) · <strong>Customer site</strong> (public services &amp; message templates) · <strong>KPI definitions</strong></li></ul><hr><h2 id="_6-me-hub-me" tabindex="-1">6. Me hub (<code>/me</code>) <a class="header-anchor" href="#_6-me-hub-me" aria-label="Permalink to &quot;6. Me hub (`/me`)&quot;">​</a></h2><p>Personal self-service for every staff member (<a href="/rakkii-cars-guide/me/">Me hub</a>). Owners open on <strong>My profile</strong>; other staff open on <strong>Time clock</strong>.</p><table tabindex="0"><thead><tr><th>Menu item</th><th>Path</th><th>Who sees it</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Time clock</strong></td><td><code>/me/clock</code></td><td>Lead Technician, Sales Agent</td><td>Self clock-in/clock-out with live Manila time, shift photo proof (when required), GPS check/off-site reason, and <strong>Today</strong> punches. (Owners do not clock in.)</td><td><a href="/rakkii-cars-guide/me/">Me hub</a></td></tr><tr><td><strong>My payslip</strong></td><td><code>/me/payslip</code></td><td>Lead Technician, Sales Agent (and Shop Owner only if on payroll)</td><td>Lists locked payroll periods and opens frozen payslip breakdowns (hours, OT, leave, premiums, allowances, statutory deductions, loans, net pay) for print/PDF.</td><td><a href="/rakkii-cars-guide/me/">Me hub</a></td></tr><tr><td><strong>Leave</strong></td><td><code>/me/leave</code></td><td>Lead Technician, Sales Agent</td><td>Shows <strong>Vacation</strong>, <strong>Sick</strong>, <strong>Unpaid</strong>, and <strong>SIL</strong> balances, <strong>Request leave</strong>, and <strong>My requests</strong> with <strong>Cancel</strong>. (Owners do not file personal leave.)</td><td><a href="/rakkii-cars-guide/me/">Me hub</a></td></tr><tr><td><strong>My overtime</strong></td><td><code>/me/overtime</code></td><td>Lead Technician, Sales Agent</td><td>Personal weekly <strong>Punches</strong> register plus <strong>My overtime</strong> claims and <strong>Request OT</strong>. (Owners do not claim overtime.)</td><td><a href="/rakkii-cars-guide/me/">Me hub</a></td></tr><tr><td><strong>My commission</strong></td><td><code>/me/commission</code></td><td>Staff with commission lines</td><td>Opens your commission view directly inside the <strong>Me</strong> hub.</td><td><a href="/rakkii-cars-guide/sales/">Your day in sales</a></td></tr><tr><td><strong>My incentive</strong></td><td><code>/me/incentive</code></td><td>Sales Agent (and Shop Owner if on an active incentive target)</td><td>Opens your quarterly unit incentive progress inside the <strong>Me</strong> hub.</td><td><a href="/rakkii-cars-guide/sales/">Your day in sales</a></td></tr><tr><td><strong>My profile</strong></td><td><code>/me/profile</code></td><td>Everyone</td><td>Personal employee record (identity, employment, pay, leave, scorecards) plus <strong>Add photo</strong> / <strong>Change photo</strong> / <strong>Remove photo</strong> for your avatar.</td><td><a href="/rakkii-cars-guide/me/">Me hub</a></td></tr></tbody></table>',43)])])}const u=e(n,[["render",a]]);export{p as __pageData,u as default};
